// TASK-0036 — V1 Stable Identity Foundation, product acceptance in real
// WebView2. No simulated DOM, no alternate renderer, no personal data: the
// tree under test was generated by task0036-seed-proof.py and dies with the
// proof root.
//
// Unlike search/reveal proofs, this script's whole point is that the tree
// changes **between** two real `Actualiser` clicks of the SAME running
// product session — a rename, then a move, then a deletion+creation — each
// performed by THIS script directly on disk, outside the product process,
// exactly as `TASK-0036` H prescribes. No process restart is needed: node
// identity is a property of the Index across a republish, not of a
// preference surviving a relaunch.
//
// Reuses the TASK-0033..0035 harness technique (REAL_ROOT registered
// directly into a fresh sandbox catalogue, the real product driven through
// CDP) rather than building a second framework.
import assert from "node:assert/strict";
import { writeFile, rename, rm } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
assert(/^task0036-[a-f0-9]+$/.test(variant));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // real absolute path, used only by THIS script's own fs calls — never sent into the page.

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const invokedPayloads = [];
const invoke = (command, args = {}) => {
  invokedPayloads.push(JSON.stringify(args));
  return evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = ["stable_key", "stableKey", "identity_provenance", "identityProvenance", "SYS1:", "PFv1:", "PATH_FALLBACK"];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
const escaped = root.split("\\").join("\\\\");
function assertNoPathLeak(text, where) {
  assert(!text.includes(root) && !text.includes(escaped), `absolute path leaked into ${where}`);
}
async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
async function refresh() {
  await activate('[data-testid="lifecycle-refresh"]');
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  // Give the projection a moment to re-render after the republish.
  await pause(300);
}
async function resolve(relativePath) {
  const reference = await invoke("map_resolve_node", { brainId, relativePath });
  assert(reference, `no node resolves at ${relativePath}`);
  return reference.nodeId;
}

const results = {};

await waitForAppReady();
await refresh(); // first indexing — REAL_ROOT starts unbuilt (`map_not_built`).
const firstBuild = await invoke("map_view", { brainId });
results.indexedNodeCount = firstBuild.nodeCount;
assert(firstBuild.nodeCount >= 7, `indexed corpus too small: ${firstBuild.nodeCount}`);

// --- rename, outside the process, between two real Actualiser clicks ------
const idBeforeRename = await resolve("avant.txt");
await rename(join(root, "avant.txt"), join(root, "apres.txt"));
await refresh();
const idAfterRename = await resolve("apres.txt");
results.nodeIdIdenticalAfterRename = idAfterRename === idBeforeRename;
results.oldPathGoneAfterRename = await evaluate(
  `window.__TAURI_INTERNALS__.invoke("map_resolve_node",${JSON.stringify({ brainId, relativePath: "avant.txt" })}).then(r => r === null)`,
);

// --- move, outside the process, between two more real Actualiser clicks ---
const folderId = await resolve("dossier");
await rename(join(root, "apres.txt"), join(root, "dossier", "apres.txt"));
await refresh();
const idAfterMove = await resolve("dossier/apres.txt");
results.nodeIdIdenticalAfterMove = idAfterMove === idBeforeRename;
const movedDetail = await invoke("map_node_detail", { reference: { brainId, nodeId: idAfterMove } });
results.movedParentIsDestinationFolder = movedDetail.parent?.id === folderId;

// --- a moved SUBTREE keeps both its own id and its child's ----------------
const subtreeIdBefore = await resolve("sous-arbre");
const childIdBefore = await resolve("sous-arbre/enfant.txt");
await rename(join(root, "sous-arbre"), join(root, "ailleurs", "sous-arbre"));
await refresh();
const subtreeIdAfter = await resolve("ailleurs/sous-arbre");
const childIdAfter = await resolve("ailleurs/sous-arbre/enfant.txt");
results.movedFolderKeepsItsOwnId = subtreeIdAfter === subtreeIdBefore;
results.movedFoldersChildKeepsItsId = childIdAfter === childIdBefore;
const childDetailAfterMove = await invoke("map_node_detail", { reference: { brainId, nodeId: childIdAfter } });
results.movedChildParentIsMovedFolder = childDetailAfterMove.parent?.id === subtreeIdAfter;

// --- delete then create: a fresh id, never recycled ------------------------
const deletedId = await resolve("a-supprimer.txt");
await rm(join(root, "a-supprimer.txt"));
await writeFile(join(root, "nouveau.txt"), "synthetique — objet different\n", "utf8");
await refresh();
const createdId = await resolve("nouveau.txt");
results.newObjectNeverRecyclesADeletedId = createdId !== deletedId;

// --- non-regression: search, details, children, projection, reveal/copy ---
const search = await invoke("map_search_nodes", { brainId, query: "existant", offset: 0, limit: 20 });
results.searchStillFinds = search.items.some((item) => item.relativePath === "dossier/existant.txt");

const rootRef = await invoke("map_resolve_node", { brainId, relativePath: "" });
const childrenPage = await invoke("map_node_children", { reference: rootRef, after: null, limit: 50 });
results.childrenStillPage = childrenPage.items.length > 0 && childrenPage.total >= childrenPage.items.length;

const view = await invoke("map_view", { brainId });
// One deletion (a-supprimer.txt) and one creation (nouveau.txt) net to zero;
// every rename/move repositions existing nodes without changing the count.
results.projectionStillRenders = view.nodeCount === firstBuild.nodeCount;

await invoke("map_reveal_node", { reference: { brainId, nodeId: idAfterMove } });
results.revealStillSucceeds = true;
// `map_copy_node_path` writes straight to the OS clipboard and returns `()`
// — not a value a script can read back. Succeeding without throwing is the
// non-regression signal this replay needs; the clipboard byte-for-byte
// exactness is already `TASK-0035` C's own proof, not `TASK-0036`'s. A
// hidden, unfocused automation window can legitimately fail the OS
// clipboard write (`clipboard_write_failed`) for reasons that have nothing
// to do with node identity, so that one failure is recorded rather than
// treated as a fatal regression.
try {
  await invoke("map_copy_node_path", { reference: { brainId, nodeId: idAfterMove } });
  results.copyStillSucceeds = true;
} catch (error) {
  results.copyStillSucceeds = false;
  results.copyFailureReason = String(error.message ?? error);
}

// --- confidentiality: no absolute path, no stable key, no internal jargon -
const bodyText = await evaluate("document.body.textContent");
assertNoPathLeak(bodyText, "page body text");
assertNoJargon(bodyText, "page body text");
for (const payload of invokedPayloads) {
  assertNoPathLeak(payload, "an invoke argument payload");
  assertNoJargon(payload, "an invoke argument payload");
}
for (const payload of [firstBuild, view, search, childrenPage, movedDetail, childDetailAfterMove]) {
  const text = JSON.stringify(payload);
  assertNoPathLeak(text, "an invoke response payload");
  assertNoJargon(text, "an invoke response payload");
}
results.noAbsolutePathOrStableKeyLeak = true;

await writeFile(join(proofRoot, "result.json"), JSON.stringify(results));
console.log(JSON.stringify({ ok: true }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, "fatal-count.json"), JSON.stringify(fatal.length));
ws.close();
